<aside class="pm-aside">
    <style>
        .pm-aside { --pm-border:rgba(120,145,190,.2); --pm-muted:#aab4c9; display:flex; flex-direction:column; gap:.8rem; color:#f5f7ff; }
        .pm-aside * { box-sizing:border-box; }
        .pm-aside-card { padding:.9rem 1rem; border:1px solid var(--pm-border); border-radius:1rem; background:#111725e0; box-shadow:0 12px 30px #0003; }
        .pm-aside-title { display:flex; align-items:center; gap:.6rem; margin:0 0 .8rem; color:#f2f4fc; font-size:.95rem; font-weight:700; }
        .pm-aside-title svg { width:1.15rem; height:1.15rem; color:#c0c9e0; }
        .pm-server-details { display:flex; align-items:center; gap:.8rem; padding:.5rem .1rem .1rem; }
        .pm-server-icon { display:grid; place-items:center; width:3.2rem; height:3.2rem; flex:none; border:1px solid var(--pm-border); border-radius:.7rem; background:linear-gradient(145deg,#294934,#15241e); color:#8ee7a2; }
        .pm-server-icon svg { width:2rem; height:2rem; }.pm-server-details strong { display:block; }.pm-server-details small { display:block; margin:.2rem 0 .45rem; color:var(--pm-muted); }
        .pm-status { display:inline-flex; align-items:center; gap:.4rem; padding:.22rem .65rem; border-radius:999px; background:#073e2b; color:#4af2a2; font-size:.78rem; font-weight:700; }.pm-status:before { content:""; width:.4rem; height:.4rem; border-radius:50%; background:currentColor; box-shadow:0 0 10px currentColor; }.pm-status.offline { background:#422029; color:#ff8494; }
        .pm-action { display:flex; align-items:center; gap:.65rem; width:100%; padding:.65rem .2rem; border:0; border-bottom:1px solid var(--pm-border); background:transparent; color:#e6eaf5; text-align:left; font:inherit; font-size:.82rem; text-decoration:none; cursor:pointer; }.pm-action:last-child { border-bottom:0; padding-bottom:.1rem; }.pm-action:hover { color:#a9a0ff; }.pm-action svg { width:1.05rem; height:1.05rem; flex:none; color:#aab6d0; }
        .pm-stat { display:flex; align-items:center; gap:.65rem; padding:.55rem 0; border-bottom:1px solid var(--pm-border); color:#d8deed; font-size:.82rem; }.pm-stat:last-child { border:0; padding-bottom:.1rem; }.pm-stat-icon { display:grid; place-items:center; width:1.8rem; height:1.8rem; border-radius:.5rem; background:#172b28; color:#35e89a; }.pm-stat:nth-child(2) .pm-stat-icon { background:#282414; color:#f5c342; }.pm-stat:nth-child(3) .pm-stat-icon { background:#211d39; color:#a28bff; }.pm-stat-icon svg { width:1rem; height:1rem; }.pm-stat strong { margin-left:auto; color:white; font-size:1.05rem; }
        @media(max-width:850px){.pm-aside{display:grid;grid-template-columns:repeat(2,minmax(0,1fr))}}@media(max-width:600px){.pm-aside{grid-template-columns:1fr}}
    </style>
    <section class="pm-aside-card">
        <h2 class="pm-aside-title"><svg viewBox="0 0 24 24" fill="none"><path d="m12 2 9 5v10l-9 5-9-5V7l9-5Z" stroke="currentColor" stroke-width="1.7"/><path d="m12 7 4.5 2.5v5L12 17l-4.5-2.5v-5L12 7Z" stroke="currentColor" stroke-width="1.5"/></svg>{{ trans('pelican-minecraft-plugins::strings.page.server_information') }}</h2>
        <div class="pm-server-details"><span class="pm-server-icon"><svg viewBox="0 0 24 24" fill="none"><path d="M3 8 12 3l9 5v9l-9 5-9-5V8Z" stroke="currentColor" stroke-width="1.7"/><path d="m3 8 9 5 9-5M12 13v9" stroke="currentColor" stroke-width="1.7"/></svg></span><span><strong>{{ $server->name }}</strong><small>{{ $loader?->getLabel() ?? trans('pelican-minecraft-plugins::strings.page.unknown') }} · {{ $minecraftVersion ?? trans('pelican-minecraft-plugins::strings.page.unknown') }}</small><span class="pm-status {{ $serverStatusTone }}">{{ $serverStatus }}</span></span></div>
    </section>
    <section class="pm-aside-card">
        <h2 class="pm-aside-title"><svg viewBox="0 0 24 24" fill="none"><path d="M12 3 3 8l9 5 9-5-9-5Zm-9 5v9l9 5 9-5V8M12 13v9" stroke="currentColor" stroke-width="1.7" stroke-linejoin="round"/></svg>{{ trans('pelican-minecraft-plugins::strings.page.quick_actions') }}</h2>
        <button type="button" class="pm-action" wire:confirm="{{ trans('pelican-minecraft-plugins::strings.modals.bulk_update_confirmation') }}" wire:click="updateAllPlugins"><svg viewBox="0 0 24 24" fill="none"><path d="M20 7v5h-5M4 17v-5h5m10-1a7 7 0 0 0-12-4L4 9m16 6-3 2a7 7 0 0 1-12-4" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round"/></svg>{{ trans('pelican-minecraft-plugins::strings.actions.update_all_plugins') }}</button>
        <button type="button" class="pm-action" wire:click="scanPlugins"><svg viewBox="0 0 24 24" fill="none"><path d="M10 4a6 6 0 1 0 0 12 6 6 0 0 0 0-12Zm4.5 10.5L20 20m-10-13v6m-3-3h6" stroke="currentColor" stroke-width="1.7" stroke-linecap="round"/></svg>{{ trans('pelican-minecraft-plugins::strings.actions.scan') }}</button>
        <a class="pm-action" href="{{ \App\Filament\Server\Resources\Files\Pages\ListFiles::getUrl(['path' => $pluginFolder]) }}"><svg viewBox="0 0 24 24" fill="none"><path d="M3 6a2 2 0 0 1 2-2h5l2 2h7a2 2 0 0 1 2 2v10a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2V6Z" stroke="currentColor" stroke-width="1.7"/></svg>{{ $type === \FateFighter\MinecraftPlugins\Enums\ModrinthProjectType::Plugin ? trans('pelican-minecraft-plugins::strings.page.open_plugin_folder') : trans('pelican-minecraft-plugins::strings.page.open_folder', ['folder' => $pluginFolder]) }}</a>
    </section>
    <section class="pm-aside-card">
        <div class="pm-stat"><span class="pm-stat-icon"><svg viewBox="0 0 24 24" fill="none"><path d="m12 2 9 5v10l-9 5-9-5V7l9-5Z" stroke="currentColor" stroke-width="1.8"/><path d="M12 7v10" stroke="currentColor" stroke-width="1.8"/></svg></span>{{ trans('pelican-minecraft-plugins::strings.page.total_plugins') }}<strong>{{ $installedCount }}</strong></div>
        <div class="pm-stat"><span class="pm-stat-icon"><svg viewBox="0 0 24 24" fill="none"><path d="M12 3v18m-7-7 7 7 7-7M5 7l7-4 7 4" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round"/></svg></span>{{ trans('pelican-minecraft-plugins::strings.page.available_updates') }}<strong>{{ $availableUpdatesCount ?? 0 }}</strong></div>
        <div class="pm-stat"><span class="pm-stat-icon"><svg viewBox="0 0 24 24" fill="none"><path d="m12 2 9 5v10l-9 5-9-5V7l9-5Z" stroke="currentColor" stroke-width="1.8"/></svg></span>{{ trans('pelican-minecraft-plugins::strings.page.supported_sources') }}<strong>1</strong></div>
    </section>
</aside>
